```go
package main

import (
    "fmt"
    "strings"
)

func main() {
    fmt.Println(strings.EqualFold("Go", "gO"))
    fmt.Println(strings.EqualFold("AB", "ab"))
    fmt.Println(strings.EqualFold("ß", "ss"))
}
```
The outputs are true, true, and false. EqualFold intentionally does not expand `ß` into two letters.
